xml.Script:
        A := 2;
        B := 2;
        C := 2;

        if not RequestNumbers('Input cuboid orders', 'Width:', 'Depth:', 'Height:', A, B, C) then
          ShowMessage('Cancelled');


        if A > 6 then
          ShowMessage('The width can not exceed 6!');

        if B > 6 then
          ShowMessage('The depth can not exceed 6!');

        if C > 6 then
          ShowMessage('The height can not exceed 6!');

        A := Max(Min(A, 6), 2);
        B := Max(Min(B, 6), 2);
        C := Max(Min(C, 6), 2);

        W := 0.5;

        D0A := 2 * W / A;
        for i := 1 to A - 1 do
            Da[i] := -W + D0A * i;
        for i := A to 6 do
            Da[i] := Da[1];

        D0B := 2 * W / B;
        for i := 1 to B - 1 do
            Db[i] := -W + D0B * i;
        for i := B to 6 do
            Db[i] := Db[1];

        D0C := 2 * W / C;
        for i := 1 to C - 1 do
            Dc[i] := -W + D0C * i;
        for i := C to 6 do
            Dc[i] := Dc[1];

        Delta := 0.002;
        R := W * 0.98;
        D := W + Delta;

        clBlue   := '0000C8';
        clGreen  := '009600';
        clRed    := 'C80000';
        clOrange := 'FF800A';
        clYellow := 'FFFF00';
        clWhite  := 'FFFFFF';

        Ang := Pi / 2;
        amg := 2 * Pi;
